using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app",
    Description = "Returns application configuration data")]
public static class ConfigResource
{
    [McpServerResourceTemplate(UriTemplate = "config://app/{section}",
        Name = "App Config Section",
        Description = "Returns configuration for a named section",
        MimeType = "application/json")]
    public static string GetConfigSection(string section)
    {
        var configs = new Dictionary<string, object>
        {
            ["database"] = new { Host = "db.example.com", Port = 5432, MaxConnections = 20 },
            ["logging"]  = new { Level = "Information", Format = "json", Targets = new[] { "console", "file" } },
            ["features"] = new { DarkMode = true, BetaAccess = false, MaxUploadMb = 50 },
        };

        if (!configs.TryGetValue(section, out var config))
            return JsonSerializer.Serialize(new { error = $"Unknown section: {section}" });

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

